"""Geometry as on the x87 FPU (Menue.Pas): Winkel, WinkelDifferenz, Distanz."""

import math
from pathlib import Path

from psi_gw.perception.geometry import distanz, real_const, winkel, winkel_differenz, PI_EXT

DATA = Path(__file__).parent / "data" / "x87_winkel_sample.txt"


def test_winkel_matches_the_fpu():
    """Sample of the table generated by scripts/x87_winkel.c under Wine (all vectors up to 12,
    the FPATAN exceptions, 1500 random vectors up to 160)."""
    wrong = []
    for line in DATA.read_text().split("\n")[:-1]:
        o, a, bits = line.split()
        o, a = int(o), int(a)
        expected = float.fromhex(f"0x1.{int(bits, 16) & ((1 << 52) - 1):013x}p{((int(bits, 16) >> 52) & 0x7FF) - 1023}")
        if winkel((a, o), (0, 0)) != expected:
            wrong.append((o, a))
    assert not wrong


def test_winkel_directions():
    assert winkel((0, 0), (0, 0)) == float(real_const(3 * PI_EXT / 2))
    assert winkel((1, 0), (0, 0)) == float(real_const(PI_EXT))  # vector to the left
    assert winkel((0, 1), (0, 0)) == float(real_const(PI_EXT / 2))


def test_winkel_differenz_keeps_80_bit_residue():
    """2*pi stored as a real minus 2*pi in 80 bits is not 0 on the FPU."""
    two_pi_real = real_const(2 * PI_EXT)
    d = winkel_differenz(two_pi_real, 0.0)
    assert 0 < d < 1e-15
    assert winkel_differenz(1.0, 1.0) == 0.0


def test_distanz():
    assert distanz((0, 0), (3, 4)) == 5.0 and distanz((1, 1), (1, 1)) == 0.0
    assert abs(distanz((0, 0), (1, 1)) - math.sqrt(2)) < 1e-15
